//import
import '../../../styles/cards.css';
//function 
const Card = (props)=>{
    return(
        <div>
            <h2 class="section-title">Donate Item</h2>
            <div class="card">
                <h4 class="card-title">STAR (Special Treatment & Recovery)</h4>
                <p class="card-text">
                Dogs and cats requiring extensive medical and/or surgical care often arrive at ACC. The STAR (Special Treatment & Recovery) Fund is used to pay for medical care that only a specialized facility can provide.
                </p>
            </div>
        </div>
    )
}

//export
export default Card
